        int units = 250;
        double bill = 0.0;

        if (units <= 100) {
            bill = units * 1.00;
        } else if (units <= 200) {
            bill = (100 * 1.00) + ((units - 100) * 1.50);
        } else {
            bill = (100 * 1.00) + (100 * 1.50) + ((units - 200) * 2.00);
        }

        System.out.println("Units Consumed: " + units);
        System.out.printf("Total Electricity Bill: $%.2f%n", bill);
