public class Main {
    public static void main(String[] args) {
        int gallons = 3500;
        double bill;
        if (gallons <= 1000) {
            bill = 10.0;
        } else if (gallons <= 3000) {
            bill = 10.0 + (gallons - 1000) * 0.005;
        } else {
            bill = 10.0 + (2000 * 0.005) + (gallons - 3000) * 0.008;
        }
        System.out.printf("Water Bill: $%.2f%n", bill);
    }
}

