public class Main {
    public static void main(String[] args) {
        int hoursParked = 5;
        int fee = 0;
        if (hoursParked <= 2) {
            fee = 0;
        } else if (hoursParked <= 6) {
            fee = (hoursParked - 2) * 3;
        } else {
            fee = (4 * 3) + ((hoursParked - 6) * 2);
            if (fee > 25) fee = 25;
        }
        System.out.println("Parking Fee: $" + fee);
    }
}

